<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{$uid=(int)requireAuth()->id;$conn=db();requirePermission($conn,$uid,'reports.view');$s=$conn->prepare('SELECT p.id,p.contribution,p.period_start,p.period_end,p.basis_kind,p.basis_amount,p.rate,p.calculated_amount,p.status,p.notes,p.reviewed_by,p.reviewed_at,p.locked_by,p.locked_at,p.filed_by,p.filed_at,p.created_at,p.updated_at,c.legal_basis FROM erp_contribution_periods p JOIN erp_contribution_configs c ON c.id=p.config_id WHERE p.user_id=? ORDER BY p.period_start DESC,p.contribution');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();jsonResponse(['success'=>true,'formula'=>'amount=round(basis_amount*effective_rate/100,3)','data'=>$rows]);}catch(Throwable $e){reportFailureResponse($e,'Could not load the contribution periods.','CONTRIBUTION_PERIOD_LOAD_FAILED');}
